import{_ as d,o as a,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"سادھائی کی سطحوں کی یکساں تقسیم","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0014-修炼境界统一划分.md","filePath":"ur/0014-修炼境界统一划分.md"}'),o={name:"ur/0014-修炼境界统一划分.md"};function r(e,t,u,h,q,n){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="سادھائی-کی-سطحوں-کی-یکساں-تقسیم" tabindex="-1">سادھائی کی سطحوں کی یکساں تقسیم <a class="header-anchor" href="#سادھائی-کی-سطحوں-کی-یکساں-تقسیم" aria-label="Permalink to &quot;سادھائی کی سطحوں کی یکساں تقسیم&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>14</td></tr><tr><td>ماڈیول</td><td>کائنات کے قوانین اور سادھائی کے نظام</td></tr><tr><td>کلیدی الفاظ</td><td>سطح کی تقسیم، یکساں معیار، نو سطحیں، کراس سسٹم موازنہ، اینکر سرٹیفیکیشن</td></tr></tbody></table><h2 id="اولًا-یکساں-سطح-کی-تقسیم-کی-ضرورت" tabindex="-1">اولًا. یکساں سطح کی تقسیم کی ضرورت <a class="header-anchor" href="#اولًا-یکساں-سطح-کی-تقسیم-کی-ضرورت" aria-label="Permalink to &quot;اولًا. یکساں سطح کی تقسیم کی ضرورت&quot;">​</a></h2><p>اینکر سمبیوٹک تہذیب کے قیام سے پہلے، ہینگ یوآن ژو میں ہزاروں سادھائی کے نظام موجود تھے، اور ہر نظام کے اپنے آزاد سطح کی تقسیم کے معیار تھے۔ اس غیر منظم سطح کے نظام نے ایک سیریز مسائل پیدا کیے تھے: مختلف نظاموں کے سادھکوں کے درمیان طاقت کا موازنہ کرنا مشکل تھا، کراس سسٹم رابطے اور تعاون میں مشترکہ زبان کی کمی تھی، وسائل کی تقسیم اور سماجی حیثیت کی تشخیص میں یکساں بنیاد کی کمی تھی، یہاں تک کہ &quot;ایک ہی سطح لیکن مختلف طاقت&quot; کی سنگین ناانصافی کا واقعہ بھی سامنے آیا تھا۔</p><p>اینکر سمبیوٹک تہذیب کے قیام کے بعد، اس مسئلے کو حل کرنے کے لیے، وان-ژو ریپبلکن کونسل کے ماتحت &quot;سادھائی معیار کمیٹی&quot; کی قیادت میں، تین سو نظاموں کے نمائندہ سادھکوں کے ساتھ مل کر، طویل تحقیق اور استدلال کے بعد، یہ &quot;سادھائی کی سطحوں کی یکساں تقسیم کا معیار&quot; وضع کیا گیا۔ یہ معیار کسی ایک نظام کے سطح کے نام پر مبنی نہیں ہے، بلکہ سادھک کی کائناتی بنیادی قوانین کی سمجھ کی گہرائی، توانائی کے کنٹرول کی درستگی، شعور کے ارتقاء کی ڈگری، اور سمبیوٹک نیٹ ورک میں شراکت کی ڈگری — ان چار جہتوں کو بنیادی اشاریے کے طور پر لے کر، ایک کراس سسٹم عام سطح کی تقسیم کا نظام قائم کیا ہے۔</p><p>یکساں سطح کی تقسیم کا بنیادی اصول &quot;نام سے زیادہ حقیقت کو اہمیت دینا&quot; ہے: چاہے سادھک کون سا نظام استعمال کرے یا سطح کا نام کچھ بھی ہو، جب تک اس کی حقیقت یکساں معیار کی متعلقہ سطح تک نہ پہنچ جائے، اسے اس سطح کے طور پر تسلیم نہیں کیا جاتا۔ یہ اصول سطح کی تشخیص کی انصاف اور حقیقت پسندی کو یقینی بناتا ہے۔</p><h2 id="ثانیًا-نو-سطحوں-کا-عمومی-جائزہ" tabindex="-1">ثانیًا. نو سطحوں کا عمومی جائزہ <a class="header-anchor" href="#ثانیًا-نو-سطحوں-کا-عمومی-جائزہ" aria-label="Permalink to &quot;ثانیًا. نو سطحوں کا عمومی جائزہ&quot;">​</a></h2><p>یکساں سطح کی تقسیم کا معیار سادھک کے ارتقاء کے سفر کو نو سطحوں میں تقسیم کرتا ہے، نچلے سے اونچے کی ترتیب میں:</p><table tabindex="0"><thead><tr><th>سطح کی ترتیب</th><th>سطح کا نام</th><th>بنیادی خصوصیت</th><th>بنیادی تین بنیادیوں کی سطح سے موازنہ</th><th>سماجی کردار کی وضاحت</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>توانائی احساس کی سطح</td><td>ابتدائی طور پر کائناتی توانائی اور قوانین کی موجودگی کو محسوس کرنا، باقاعدہ سادھائی شروع کرنا</td><td>ابتدائی بصیرت / زندگی احساس / جگہ جاننا</td><td>نوزائیدہ سیکھنے والا</td></tr><tr><td>دوسری سطح</td><td>توانائی گاڑھا کرنے کی سطح</td><td>توانائی کو مستحکم طریقے سے جذب اور گاڑھا کرنے کے قابل، بنیادی اندرونی چکر قائم کرنا</td><td>تخمین / چکر / جگہ کنٹرول</td><td>ابتدائی درجے کا سادھک</td></tr><tr><td>تیسری سطح</td><td>توانائی تبدیلی کی سطح</td><td>توانائی کی پاکیزگی اعلیٰ سطح تک پہنچ جاتی ہے، توانائی کو مختلف اطلاقات میں تبدیل کرنے کے قابل</td><td>تکرار / مسلسل زندگی / جگہ تبدیلی</td><td>درمیانی درجے کا سادھک</td></tr><tr><td>چوتھی سطح</td><td>قانونی توانائی کی سطح</td><td>قوانین کو سمجھنا اور کنٹرول کرنا شروع کرنا، توانائی اور قوانین ابتدائی طور پر مل جاتے ہیں</td><td>آمیزش / زندگی تبدیلی / قانونی جگہ</td><td>اعلیٰ درجے کا سادھک</td></tr><tr><td>پانچویں سطح</td><td>داؤ توانائی کی سطح</td><td>کسی ایک شعبے کے قوانین کی گہری سمجھ، ذاتی &quot;داؤ&quot; کی تشکیل</td><td>بنیادی / بنیادی زندگی / بنیادی جگہ</td><td>ماسٹر درجے کا سادھک</td></tr><tr><td>چھٹی سطح</td><td>داؤ کے ساتھ اتحاد کی سطح</td><td>ذاتی داؤ اور کائناتی بنیادی قوانین گہرا اتحاد، ہر حرکت داؤ کے مطابق</td><td>واحد نظام کی پانچویں سطح سے بالاتر</td><td>گرانڈ ماسٹر درجے کا سادھک</td></tr><tr><td>ساتویں سطح</td><td>حد توڑنے کی سطح</td><td>جہاز کے قوانین کی حدود کو توڑنے کے قابل، کراس پلین مستحکم کارروائی کے قابل</td><td>—</td><td>جہاز سطح کے طاقتور</td></tr><tr><td>آٹھویں سطح</td><td>تخلیق کی سطح</td><td>الگ تھلگ جگہ میں مکمل دنیا اور قانونی نظام تخلیق کرنے کے قابل</td><td>—</td><td>عالمی سطح کے طاقتور</td></tr><tr><td>نوویں سطح</td><td>بنیادی سطح</td><td>کائنات کی بنیاد کو چھوتا ہے، کائناتی قوانین کی باریک ایڈجسٹمنٹ اور بہتری میں حصہ لینے کے قابل</td><td>—</td><td>کائناتی سطح کے طاقتور</td></tr></tbody></table><p>نو سطحوں میں، پہلی سے پانچویں سطح &quot;پانچ عام سادھائی سطحیں&quot; ہیں، جو زیادہ تر سادھک کوشش کے ذریعے حاصل کر سکتے ہیں؛ چھٹی سے نوویں سطح &quot;چار مقدس سادھائی سطحیں&quot; ہیں، جن تک پہنچنے کے لیے انتہائی اعلیٰ صلاحیت، موقع اور کوشش درکار ہے، اور ہر سطح کی کامیابی ایک کائناتی سطح کا بڑا واقعہ ہے۔</p><h2 id="ثالثًا-ہر-سطح-کے-تفصیلی-معیار" tabindex="-1">ثالثًا. ہر سطح کے تفصیلی معیار <a class="header-anchor" href="#ثالثًا-ہر-سطح-کے-تفصیلی-معیار" aria-label="Permalink to &quot;ثالثًا. ہر سطح کے تفصیلی معیار&quot;">​</a></h2><h3 id="_3-1-پہلی-سطح-توانائی-احساس-کی-سطح" tabindex="-1">3.1 پہلی سطح: توانائی احساس کی سطح <a class="header-anchor" href="#_3-1-پہلی-سطح-توانائی-احساس-کی-سطح" aria-label="Permalink to &quot;3.1 پہلی سطح: توانائی احساس کی سطح&quot;">​</a></h3><p>توانائی احساس کی سطح سادھائی کا نقطہ آغاز ہے، اور اس کا بنیادی نقطہ &quot;احساس&quot; ہے۔ توانائی احساس کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>کائنات میں آزادانہ توانائی (روحانی توانائی، قانون کی طاقت وغیرہ) کو مستحکم طریقے سے محسوس کرنے کے قابل</li><li>بنیادی سادھائی کے طریقوں کے ذریعے تھوڑی سی توانائی کو جسم میں جذب کرنے کے قابل</li><li>ابتدائی توانائی احساس کی شعور قائم کرنا، مختلف قسم کی توانائی میں فرق کرنے کے قابل</li><li>توانائی کے جذب سے جسمانی صحت میں ابتدائی بہتری</li></ul><p>توانائی احساس کی سطح کے سادھک سماج میں &quot;نوزائیدہ سیکھنے والے&quot; ہیں، اور ان کا بنیادی کام بنیاد بنانا اور اپنے لیے موزوں سادھائی کا نظام تلاش کرنا ہے۔ توانائی احساس کی سطح کی کامیابی میں عام طور پر چند ہفتوں سے چند ماہ کی باقاعدہ سادھائی درکار ہوتی ہے۔</p><h3 id="_3-2-دوسری-سطح-توانائی-گاڑھا-کرنے-کی-سطح" tabindex="-1">3.2 دوسری سطح: توانائی گاڑھا کرنے کی سطح <a class="header-anchor" href="#_3-2-دوسری-سطح-توانائی-گاڑھا-کرنے-کی-سطح" aria-label="Permalink to &quot;3.2 دوسری سطح: توانائی گاڑھا کرنے کی سطح&quot;">​</a></h3><p>توانائی گاڑھا کرنے کی سطح کا بنیادی نقطہ &quot;گاڑھا کرنا&quot; ہے۔ توانائی گاڑھا کرنے کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>کائناتی توانائی کو مستحکم طریقے سے جذب کر کے جسم میں قابل استعمال توانائی کے ذخیرے میں گاڑھا کرنے کے قابل</li><li>بنیادی اندرونی چکر کا نظام قائم کرنا، توانائی جسم میں مخصوص راستے کے مطابق گھوم سکتی ہے</li><li>گاڑھی ہوئی توانائی کو بنیادی حملہ-دفاع یا معاون اطلاقات میں استعمال کرنے کے قابل</li><li>توانائی کی پاکیزگی بنیادی معیار پر پہنچ جاتی ہے، زیادہ نجاست نہیں رکھتی</li></ul><p>توانائی گاڑھا کرنے کی سطح کے سادھک اب بنیادی سادھک کی شناخت رکھتے ہیں، اور کچھ نچلے درجے کی سادھائی کے کاموں اور سماجی خدمات میں حصہ لے سکتے ہیں۔ توانائی گاڑھا کرنے کی سطح کی کامیابی میں عام طور پر چند ماہ سے چند سال کی سادھائی درکار ہوتی ہے۔</p><h3 id="_3-3-تیسری-سطح-توانائی-تبدیلی-کی-سطح" tabindex="-1">3.3 تیسری سطح: توانائی تبدیلی کی سطح <a class="header-anchor" href="#_3-3-تیسری-سطح-توانائی-تبدیلی-کی-سطح" aria-label="Permalink to &quot;3.3 تیسری سطح: توانائی تبدیلی کی سطح&quot;">​</a></h3><p>توانائی تبدیلی کی سطح کا بنیادی نقطہ &quot;تبدیلی&quot; ہے۔ توانائی تبدیلی کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>توانائی کی پاکیزگی اعلیٰ سطح تک پہنچ جاتی ہے، ایک قسم کی توانائی کو دوسری قسم کی توانائی میں تبدیل کرنے کے قابل</li><li>توانائی اور مادے کی ابتدائی تعامل کرنے کے قابل (جیسے توانائی کو چیزوں سے جوڑنا، توانائی کو شکل دینا وغیرہ)</li><li>اندرونی چکر مستحکم اور کارآمد ہے، توانائی کی بحالی کی رفتار نمایاں طور پر بڑھ جاتی ہے</li><li>قوانین کی موجودگی اور کام کو محسوس کرنا شروع کر دیتا ہے</li></ul><p>توانائی تبدیلی کی سطح کے سادھک سماج کی مرکزی طاقت ہیں، اور درمیانی درجے کے اساتذہ، تکنیکی اہلکار، بنیادی درجے کے منتظمین وغیرہ کے عہدوں پر فائز ہو سکتے ہیں۔ توانائی تبدیلی کی سطح کی کامیابی میں عام طور پر چند سال سے ایک دہائی سے زیادہ کی سادھائی درکار ہوتی ہے۔</p><h3 id="_3-4-چوتھی-سطح-قانونی-توانائی-کی-سطح" tabindex="-1">3.4 چوتھی سطح: قانونی توانائی کی سطح <a class="header-anchor" href="#_3-4-چوتھی-سطح-قانونی-توانائی-کی-سطح" aria-label="Permalink to &quot;3.4 چوتھی سطح: قانونی توانائی کی سطح&quot;">​</a></h3><p>قانونی توانائی کی سطح کا بنیادی نقطہ &quot;قانون&quot; ہے۔ قانونی توانائی کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>کسی ایک شعبے کے بنیادی قوانین کو سمجھنے اور ابتدائی طور پر کنٹرول کرنے کے قابل</li><li>توانائی اور قوانین ابتدائی طور پر مل جاتے ہیں، &quot;قانونی طاقت&quot; نامی اعلیٰ درجے کی توانائی کی شکل پیدا ہوتی ہے</li><li>قوانین پر مبنی تکنیک اور مہارت کا استعمال کرنے کے قابل</li><li>شعور کی طاقت نمایاں طور پر بڑھ جاتی ہے، طویل عرصے کی گہری تخمین اور مراقبہ کرنے کے قابل</li></ul><p>قانونی توانائی کی سطح کے سادھک سماج کے اعلیٰ درجے کے اہلکار ہیں، اور اعلیٰ درجے کے اساتذہ، تکنیکی ماہرین، درمیانی درجے کے منتظمین وغیرہ کے عہدوں پر فائز ہو سکتے ہیں۔ قانونی توانائی کی سطح کی کامیابی میں عام طور پر ایک دہائی سے چند دہائیوں کی سادھائی درکار ہوتی ہے، اور یہ بہت سے سادھکوں کی زندگی میں پہلی بڑی رکاوٹ ہے۔</p><h3 id="_3-5-پانچویں-سطح-داؤ-توانائی-کی-سطح" tabindex="-1">3.5 پانچویں سطح: داؤ توانائی کی سطح <a class="header-anchor" href="#_3-5-پانچویں-سطح-داؤ-توانائی-کی-سطح" aria-label="Permalink to &quot;3.5 پانچویں سطح: داؤ توانائی کی سطح&quot;">​</a></h3><p>داؤ توانائی کی سطح کا بنیادی نقطہ &quot;داؤ حاصل کرنا&quot; ہے۔ داؤ توانائی کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>کسی ایک شعبے کے قوانین کی منظم اور گہری سمجھ، ذاتی منفرد &quot;داؤ&quot; کی تشکیل</li><li>ذاتی داؤ اور کائناتی قوانین کے ساتھ گونج پیدا ہوتی ہے، وسیع پیمانے پر قانون کی طاقت کو استعمال کرنے کے قابل</li><li>توانائی اور قوانین گہرا اتحاد، ہر حرکت میں قانون کی طاقت شامل ہوتی ہے</li><li>شعور اعلیٰ سطح تک ارتقا پا جاتا ہے، کراس پلین شعور احساس کرنے کے قابل</li></ul><p>داؤ توانائی کی سطح کے سادھک تہذیب کے &quot;ماسٹر&quot; ہیں، اور اپنے اپنے شعبوں میں اختیار رکھتے ہیں، تہذیبی سطح کے مشیر، عظیم اساتذہ، اعلیٰ درجے کے منتظمین وغیرہ کے عہدوں پر فائز ہو سکتے ہیں۔ داؤ توانائی کی سطح کی کامیابی کے لیے انتہائی اعلیٰ صلاحیت اور بصیرت درکار ہے، بہت سے سادھک پوری زندگی میں اس تک نہیں پہنچ پاتے۔</p><h3 id="_3-6-چھٹی-سطح-داؤ-کے-ساتھ-اتحاد-کی-سطح" tabindex="-1">3.6 چھٹی سطح: داؤ کے ساتھ اتحاد کی سطح <a class="header-anchor" href="#_3-6-چھٹی-سطح-داؤ-کے-ساتھ-اتحاد-کی-سطح" aria-label="Permalink to &quot;3.6 چھٹی سطح: داؤ کے ساتھ اتحاد کی سطح&quot;">​</a></h3><p>داؤ کے ساتھ اتحاد کی سطح کا بنیادی نقطہ &quot;داؤ کے ساتھ اتحاد&quot; ہے۔ داؤ کے ساتھ اتحاد کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>ذاتی داؤ اور کائناتی بنیادی قوانین گہرا اتحاد، &quot;آسمان اور انسان کا اتحاد&quot; کی حالت تک پہنچ جاتا ہے</li><li>وسیع پیمانے پر مقامی قوانین کے کام کرنے کے طریقے کو دوبارہ لکھنے کے قابل</li><li>زندگی کی شکل اعلیٰ جہت کی طرف ارتقا پانا شروع کر دیتی ہے، جزوی طور پر مادی جسم کی حدود سے آزاد ہو جاتی ہے</li><li>مستحکم ذاتی دائرہ (قانونی دائرہ) بنانے کے قابل</li></ul><p>داؤ کے ساتھ اتحاد کی سطح کے سادھک تہذیب کے &quot;گرانڈ ماسٹر&quot; ہیں، اور ہر شعبے کے سرکردہ شخصیات ہیں، تہذیب کی ترقی کی سمت پر اہم اثر و رسوخ رکھتے ہیں۔ داؤ کے ساتھ اتحاد کی سطح کی کامیابی ایک کائناتی سطح کا واقعہ ہے، اور اس کے لیے وقت، جگہ اور انسان کی شراکت درکار ہے۔</p><h3 id="_3-7-ساتویں-سطح-حد-توڑنے-کی-سطح" tabindex="-1">3.7 ساتویں سطح: حد توڑنے کی سطح <a class="header-anchor" href="#_3-7-ساتویں-سطح-حد-توڑنے-کی-سطح" aria-label="Permalink to &quot;3.7 ساتویں سطح: حد توڑنے کی سطح&quot;">​</a></h3><p>حد توڑنے کی سطح کا بنیادی نقطہ &quot;حد توڑنا&quot; ہے۔ حد توڑنے کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>جہاز کے قوانین کی حدود کو توڑنے کے قابل، اینکر کی حمایت کے بغیر کراس پلین عبور کرنے کے قابل</li><li>جہاز کی جھلی پر کارروائی کرنے کے قابل، جیسے جہاز کے راستے کھولنا، جہاز کی دراڑیں مرمت کرنا وغیرہ</li><li>ذاتی دائرہ چھوٹی آزاد جگہ تک پھیل سکتا ہے</li><li>زندگی کی شکل مزید اعلیٰ جہتی ہو جاتی ہے، مختلف جہازوں کے قانونی ماحول میں زندہ رہنے کے قابل</li></ul><p>حد توڑنے کی سطح کے طاقتور &quot;جہاز سطح کے&quot; وجود ہیں، اور آزادانہ طور پر جہاز سطح کے کام اور ذمہ داریاں اٹھا سکتے ہیں۔ حد توڑنے کی سطح کی کامیابی انتہائی مشکل ہے، اور پورے ہینگ یوآن ژو میں اس سطح تک پہنچنے والے سادھکوں کی تعداد محدود ہے۔</p><h3 id="_3-8-آٹھویں-سطح-تخلیق-کی-سطح" tabindex="-1">3.8 آٹھویں سطح: تخلیق کی سطح <a class="header-anchor" href="#_3-8-آٹھویں-سطح-تخلیق-کی-سطح" aria-label="Permalink to &quot;3.8 آٹھویں سطح: تخلیق کی سطح&quot;">​</a></h3><p>تخلیق کی سطح کا بنیادی نقطہ &quot;تخلیق&quot; ہے۔ تخلیق کی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>الگ تھلگ جگہ میں مکمل دنیا تخلیق کرنے کے قابل، بشمول مادہ، توانائی، قوانین، زندگی</li><li>نئی دنیا کے بنیادی قانونی نظام کو ڈیزائن اور وضع کرنے کے قابل</li><li>ذاتی دائرہ مکمل دنیا تک پھیل سکتا ہے</li><li>زندگی کی شکل اعلیٰ جہتی وجود کے قریب، ایک ساتھ متعدد جہازوں میں ظاہر ہونے کے قابل</li></ul><p>تخلیق کی سطح کے طاقتور &quot;عالمی سطح کے&quot; وجود ہیں، اور ان کی تخلیق کردہ دنیا کو سادھائی کے وسائل، تجرباتی مقامات، تہذیبی پناہ گاہوں وغیرہ کے طور پر استعمال کیا جا سکتا ہے۔ تخلیق کی سطح کی کامیابی کائنات میں سب سے نایاب واقعات میں سے ایک ہے۔</p><h3 id="_3-9-نوویں-سطح-بنیادی-سطح" tabindex="-1">3.9 نوویں سطح: بنیادی سطح <a class="header-anchor" href="#_3-9-نوویں-سطح-بنیادی-سطح" aria-label="Permalink to &quot;3.9 نوویں سطح: بنیادی سطح&quot;">​</a></h3><p>بنیادی سطح کا بنیادی نقطہ &quot;بنیاد&quot; ہے۔ بنیادی سطح تک پہنچنے کے معیار درج ذیل ہیں:</p><ul><li>کائناتی بنیادی قوانین کو چھوتا ہے، کائنات کے حتمی کام کرنے کے قواعد کو سمجھنے کے قابل</li><li>کائناتی قوانین کی باریک ایڈجسٹمنٹ اور بہتری میں حصہ لینے کے قابل، کائنات کے ارتقاء کی سمت پر اثر ڈالنے کے قابل</li><li>زندگی کی شکل کائنات کی بنیاد کے ساتھ گہرا تعلق قائم کر لیتی ہے، تقریباً لازوال ہے</li><li>کائناتی پیمانے پر بنیادی طاقت کو استعمال کرنے کے قابل</li></ul><p>بنیادی سطح کے طاقتور &quot;کائناتی سطح کے&quot; وجود ہیں، اور ہینگ یوآن ژو میں سب سے زیادہ اعلیٰ طاقت ہیں۔ بنیادی سطح تک پہنچنے والے سادھکوں کو عام طور پر &quot;جہاز کے اعلیٰ ترین طاقتور&quot; کہا جاتا ہے، اور وہ سمبیوٹک تہذیب کی &quot;20% ایکٹیویشن حکمت عملی&quot; کے بنیادی ہدف گروپ ہیں۔</p><h2 id="رابعًا-سطح-کی-سرٹیفیکیشن-کا-طریقہ-کار" tabindex="-1">رابعًا. سطح کی سرٹیفیکیشن کا طریقہ کار <a class="header-anchor" href="#رابعًا-سطح-کی-سرٹیفیکیشن-کا-طریقہ-کار" aria-label="Permalink to &quot;رابعًا. سطح کی سرٹیفیکیشن کا طریقہ کار&quot;">​</a></h2><p>سطح کی تشخیص کی انصاف اور درستگی کو یقینی بنانے کے لیے، سمبیوٹک تہذیب نے سخت سطح کی سرٹیفیکیشن کا طریقہ کار قائم کیا ہے:</p><ol><li><strong>اینکر خودکار نگرانی</strong>: سادھک اینکر نیٹ ورک سے منسلک ہونے کے بعد، اینکر اس کی توانائی کی سطح، قانون کی سمجھ، شعور کی طاقت وغیرہ جیسے اشاریوں کی مسلسل نگرانی کرے گا، اور جب اشاریے نئی سطح کے معیار پر پہنچ جائیں تو خودکار طور پر اشارہ کرے گا</li><li><strong>معیار کمیٹی کا امتحان</strong>: چوتھی سطح اور اس سے اوپر کی سطحوں کی کامیابی کے لیے، سادھائی معیار کمیٹی کی طرف سے رسمی امتحان کا اہتمام کرنا ضروری ہے، جس میں تین پہلو شامل ہیں: نظریاتی امتحان، عملی امتحان، اور شراکت کی تشخیص</li><li><strong>عام اعلان اور اعتراض کی مدت</strong>: امتحان پاس کرنے کے بعد تیس دن کے لیے عام اعلان کیا جائے گا، عام اعلان کی مدت میں کوئی بھی زندگی اعتراض اٹھا سکتی ہے، اور اگر اعتراض ثابت ہو جائے تو دوبارہ امتحان کرنا ہوگا</li><li><strong>سطح کا سرٹیفکیٹ جاری کرنا</strong>: عام اعلان میں کوئی اعتراض نہ ہونے پر، اینکر نیٹ ورک کی طرف سے یکساں سطح کا سرٹیفکیٹ جاری کیا جائے گا، اور سرٹیفکیٹ کی معلومات تہذیبی ڈیٹا بیس میں درج کی جائیں گی</li></ol><h2 id="خامسًا-سطح-اور-سماجی-حقوق-و-ذمہ-داریوں-کا-تعلق" tabindex="-1">خامسًا. سطح اور سماجی حقوق و ذمہ داریوں کا تعلق <a class="header-anchor" href="#خامسًا-سطح-اور-سماجی-حقوق-و-ذمہ-داریوں-کا-تعلق" aria-label="Permalink to &quot;خامسًا. سطح اور سماجی حقوق و ذمہ داریوں کا تعلق&quot;">​</a></h2><p>مختلف سطحوں کے سادھک سمبیوٹک تہذیب میں مختلف حقوق حاصل کرتے ہیں اور مختلف ذمہ داریاں اٹھاتے ہیں:</p><table tabindex="0"><thead><tr><th>سطح</th><th>بنیادی حقوق</th><th>بنیادی ذمہ داریاں</th></tr></thead><tbody><tr><td>توانائی احساس - توانائی گاڑھا کرنے کی سطح</td><td>بنیادی سادھائی کے وسائل مفت حاصل کرنا، عوامی سادھائی کی جگہوں کے استعمال کا حق</td><td>سادھائی کے اخلاق پر عمل کرنا، بنیادی کمیونٹی خدمات میں حصہ لینا</td></tr><tr><td>توانائی تبدیلی - قانونی توانائی کی سطح</td><td>جدید وسائل کی تقسیم کا حق، استاد کی اہلیت درخواست کا حق، کراس علاقے میں نقل و حرکت کا حق</td><td>ابتدائی سادھکوں کی رہنمائی کرنا، تکنیکی تحقیق یا سماجی خدمات میں حصہ لینا</td></tr><tr><td>داؤ توانائی - داؤ کے ساتھ اتحاد کی سطح</td><td>اعلیٰ درجے کے وسائل کی تقسیم کا حق، اینکر اعلیٰ درجے تک رسائی کا حق، تہذیبی فیصلوں میں حصہ لینے کا حق</td><td>تہذیبی سطح کے تحقیقی منصوبوں کی ذمہ داری اٹھانا، علاقائی اینکر کے استحکام کی حفاظت کرنا</td></tr><tr><td>حد توڑنے - تخلیق کی سطح</td><td>جہاز سطح کے وسائل کی تقسیم کا حق، آزاد جگہ بنانے کا حق، جہاز کے معاملات میں حصہ لینے کا حق</td><td>جہاز سطح کے کاموں کی ذمہ داری اٹھانا، جہاز کی جھلی کے استحکام کی حفاظت کرنا، کراس پلین معاملات میں حصہ لینا</td></tr><tr><td>بنیادی سطح</td><td>کائناتی سطح کے وسائل کی تقسیم کا حق، قوانین کی باریک ایڈجسٹمنٹ میں حصہ لینے کا حق، تہذیب کے اعلیٰ ترین فیصلوں میں حصہ لینے کا حق</td><td>کائنات کے مجموعی استحکام کی حفاظت کرنا، تہذیب کے ارتقاء کی سمت کی رہنمائی کرنا، اگلی نسل کے اہلکاروں کی تربیت کرنا</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سادھائی کی سطحوں کی یکساں تقسیم کا معیار اینکر سمبیوٹک تہذیب کے سادھائی نظام کی بنیادی ڈھانچے میں سے ایک ہے۔ یہ تین سو سادھائی کے نظاموں کے لیے ایک مشترکہ &quot;پیمائش کا آلہ&quot; فراہم کرتا ہے، جس سے کراس سسٹم رابطے، تعاون، مقابلہ ممکن ہو جاتا ہے، اور وسائل کی تقسیم، سماجی انتظام، اہلکاروں کی تربیت کے لیے بھی حقیقی بنیاد فراہم کرتا ہے۔ نو سطحوں کی تقسیم طبقاتی فرق پیدا کرنے کے لیے نہیں ہے، بلکہ ہر سادھک کے ارتقاء کے مرحلے کو واضح طور پر شناخت کرنے کے لیے ہے، اور اسے سب سے زیادہ موزوں مدد اور رہنمائی فراہم کرنے کے لیے ہے۔ سطح کی بلندی اختتام نہیں ہے، بلکہ اعلیٰ سطح کے سمبیوٹک ارتقاء کی طرف ایک نیا نقطہ آغاز ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (تین سو بنیادی سادھائی کے نظام کا عمومی جائزہ)</li><li>17-位面至高强者标准 (جہاز کے اعلیٰ ترین طاقتور کا معیار)</li><li>29-共生度评估体系 (سمبیوسس کی ڈگری کا تشخیصی نظام)</li></ul>',57)])])}const b=d(o,[["render",r]]);export{s as __pageData,b as default};
